public class Boxes {
    public static void main(String[] args) {
        Integer a = 127, b = 127;
        Integer c = 128, d = 128;
        Long e = 127L;
        System.out.print(a == b);
        System.out.print(" " + (c == d));
        System.out.print(" " + c.equals(d));
        System.out.print(" " + e.equals(127));
        System.out.print(" " + (c == 128));
    }
}

