public class Immutable {
    public static void main(String[] args) {
        String s = "java";
        s.toUpperCase();
        s.concat("17");
        String t = s.replace('a', 'o');
        s = s + t.substring(1, 3);
        System.out.println(s + " " + s.length());
    }
}

public class Pool {
    public static void main(String[] args) {
        String a = "hello";
        String b = "hel";
        final String c = "hel";
        String d = b + "lo";
        String e = c + "lo";
        String f = new String("hello").intern();
        System.out.println((a == d) + " " + (a == e) + " " + (a == f));
    }
}

public class Builder {
