}

public class Equality {
    public static void main(String[] args) {
        StringBuilder sb1 = new StringBuilder("ok");
        StringBuilder sb2 = new StringBuilder("ok");
        String s = "ok";
        System.out.print(sb1.equals(sb2) + " ");
        System.out.print(s.equals(sb1) + " ");
